import numpy as np

def gibbs_peak(M, n=200001):
    """Largest partial sum of the square wave on (0, pi/2]."""
    x = np.linspace(0, np.pi / 2, n)[1:]
    s = np.zeros_like(x)
    for j in range(1, M + 1):
        k = 2 * j - 1
        s += 4 / (np.pi * k) * np.sin(k * x)
    return float(s.max())

def decay_slope(b, ks):
    """Slope of ln|b_k| on ln k."""
    ks = np.asarray(ks, dtype=float)
    b = np.abs(np.asarray(b, dtype=float))
    return float(np.polyfit(np.log(ks), np.log(b), 1)[0])
